use super::ResolvedLang;

#[inline]
fn pick(
    lang: ResolvedLang,
    pt: &'static str,
    pl: &'static str,
    cs: &'static str,
    hu: &'static str,
    ro: &'static str,
    uk: &'static str,
) -> Option<&'static str> {
    Some(match lang {
        ResolvedLang::Pt => pt,
        ResolvedLang::Pl => pl,
        ResolvedLang::Cs => cs,
        ResolvedLang::Hu => hu,
        ResolvedLang::Ro => ro,
        ResolvedLang::Uk => uk,
        _ => return None,
    })
}

